-- Storage policies for the private listing-photos bucket.
-- Files are stored under "<user_id>/<filename>"; owners manage their own folder.
-- Reads are available to any authenticated user (listings are community content)
-- and are served through short-lived signed URLs generated by the app.

CREATE POLICY "listing photos readable by authenticated users"
ON storage.objects FOR SELECT
TO authenticated
USING (bucket_id = 'listing-photos');

CREATE POLICY "users upload listing photos to their own folder"
ON storage.objects FOR INSERT
TO authenticated
WITH CHECK (
  bucket_id = 'listing-photos'
  AND (storage.foldername(name))[1] = auth.uid()::text
);

CREATE POLICY "users update their own listing photos"
ON storage.objects FOR UPDATE
TO authenticated
USING (
  bucket_id = 'listing-photos'
  AND (storage.foldername(name))[1] = auth.uid()::text
);

CREATE POLICY "users delete their own listing photos"
ON storage.objects FOR DELETE
TO authenticated
USING (
  bucket_id = 'listing-photos'
  AND (storage.foldername(name))[1] = auth.uid()::text
);

CREATE POLICY "staff manage listing photos"
ON storage.objects FOR ALL
TO authenticated
USING (bucket_id = 'listing-photos' AND public.is_staff(auth.uid()))
WITH CHECK (bucket_id = 'listing-photos' AND public.is_staff(auth.uid()));
